tool_input.newString:
let lastClientX = null, lastClientY = null;
const onMouseMove = (e) => {
  if (document.pointerLockElement === canvas) {
    input.mx += e.movementX; input.my += e.movementY;
    lastClientX = e.clientX; lastClientY = e.clientY;
    return;
  }
  if (lastClientX !== null && lastClientY !== null) {
    input.mx += e.clientX - lastClientX;
    input.my += e.clientY - lastClientY;
  }
  lastClientX = e.clientX; lastClientY = e.clientY;
};
const onWheel = (e) => { input.scroll += Math.sign(e.deltaY); };
const requestLock = () => {
  if (document.pointerLockElement === canvas) return;
  try { canvas.requestPointerLock(); } catch { /* fora de user gesture — Q/E cobrem */ }
};
const onMouseDown = (e) => {
  if (e.button !== 0) return;
  if (!input.keys.has('Mouse0')) input.pressed.add('Mouse0');
  input.keys.add('Mouse0');
  requestLock();
};

